// Bake the code role's mill into the compiler.
//
// The compiler reads Term through the grammar in `deck/mill/code/tree/code`. It cannot go looking for those files at
// run time: a compiled project need not depend on `@term/mill`, and `host/line.js` is a single bundled file with
// no package tree beside it. So the merged grammar text is generated into a Term data module the compiler docks
// (compile/mill-grammar.tree), the same way `pnpm term:grammar-bundle` bakes the text grammars (decision 028 point 4:
// a generated file is generated Term, never TypeScript).
//
// Run from the Term root. Reports by default; writes only with `--commit`.
// Re-run after any change under deck/mill/code/tree/code; `pnpm term:mint-parity` fails if the baked copy is stale.

import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { loadRoleGrammar } from '@term/make/code/compile/mill-load'
import { grammarReadText } from '@term/make/code/compile/mill-grammar-text'
import { TERM_ROOT } from './root'

const TERM = TERM_ROOT
const MILL = join(TERM, 'deck/mill/code/tree')
const ROLE = process.argv.find(a => a.startsWith('--role='))?.slice(7) ?? 'code'
const OUT = join(TERM, 'deck/make/code/compile/mill-grammar.tree')
const commit = process.argv.includes('--commit')

// the read grammar is one JSON line: it goes in pieces of this many characters, cut before escaping, so a piece never
// splits an escape
const PIECE = 1000

// a text as the content of a Term text literal: every character the literal reads as syntax escaped, the line breaks
// and tabs as their escapes (decision 028 point 4, the escapes of grammar-bundle.ts)
export function escaped(text: string): string {
  return text
    .replace(/[\\<>{}]/g, character => `\\${character}`)
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t')
}

// a task answering `text`, one literal a line, joined by line breaks: a grammar edit reads as the lines it changed
function linesTask(name: string, note: string, text: string): string[] {
  const out = [`# ${note}`, `task ${name}`, '  like text', '', '  save lines, make list']

  for (const line of text.split('\n')) {
    out.push(`  push(lines, <${escaped(line)}>)`)
  }

  out.push('  back join(lines, <\\n>)', '')

  return out
}

// a task answering `text` in pieces of PIECE characters, joined with nothing between
function piecesTask(name: string, note: string, text: string): string[] {
  const out = [`# ${note}`, `task ${name}`, '  like text', '', '  save pieces, make list']

  for (let at = 0; at < text.length; at += PIECE) {
    out.push(`  push(pieces, <${escaped(text.slice(at, at + PIECE))}>)`)
  }

  out.push('  back join(pieces, <>)', '')

  return out
}

export function bakedOf(input: { role: string; mineText: string; mintText: string; mineRules: number; mintRules: number; files: number }): string {
  const read = grammarReadText(input.mineText, input.mintText)

  return [
    `# GENERATED by \`pnpm term:mill-bundle --commit\` from deck/mill/code/tree/${input.role}. Never edit this file: edit`,
    '# the grammar and run it again. `pnpm term:mint-parity` fails while the two differ.',
    '#',
    `# The ${input.role} role's mill: the \`mine\` grammar that says how to read a \`.tree\` file and the \`mint\` grammar that`,
    '# says what to build from it, baked in because the compiler cannot look for those files at run time (see',
    `# task/term/mill-bundle.ts). ${input.mineRules} mine rules, ${input.mintRules} mint rules, from ${input.files} files.`,
    '',
    'load @term/base/list',
    '  find list',
    '  find join',
    '',
    ...linesTask('baked-mine-text', 'the merged mine grammar, as its files read', input.mineText),
    ...linesTask('baked-mint-text', 'the merged mint grammar, as its files read', input.mintText),
    ...piecesTask(
      'baked-read-text',
      'the two as compile/mill-running.tree reads them (compile/mill-grammar-text.tree), one JSON text',
      read,
    ),
    '# the JSON text back as the three tables the mint grammar holds. A host value read once per process',
    'bind grammar-of-json',
    '  take text, like text',
    '  like dynamic',
    '  case node',
    '    text <(() =\\> \\{ const read = JSON.parse($text); return \\{ mine: new Map(read.mine), mint: new Map(read.mint), lean: new Map(read.lean.map((rule) =\\> [rule, true])) \\} \\})()>',
    '',
    '# the grammar the compiler mills with: all compile/minting.tree needs',
    'task read-grammar',
    '  like dynamic',
    '',
    '  back grammar-of-json(baked-read-text())',
    '',
  ].join('\n')
}

function main(): void {
  const grammar = loadRoleGrammar(MILL, ROLE)

  for (const problem of grammar.problems) {
    console.log(`  problem: ${problem}`)
  }

  if (grammar.collisions.length > 0) {
    for (const c of grammar.collisions) {
      console.log(`  collision: ${c.half} ${c.name}`)
    }

    console.log('mill-bundle: refusing to bake a grammar with collisions')
    process.exitCode = 1

    return
  }

  const built = bakedOf({
    role: ROLE,
    mineText: grammar.mineText,
    mintText: grammar.mintText,
    mineRules: grammar.mine.size,
    mintRules: grammar.mint.size,
    files: grammar.files.length,
  })

  const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : ''

  console.log(
    `mill-bundle: ${grammar.mine.size} mine rules, ${grammar.mint.size} mint rules, ${grammar.files.length} files`,
  )

  if (built === current) {
    console.log('mill-bundle: the baked grammar is current')

    return
  }

  if (commit) {
    writeFileSync(OUT, built)
    console.log(`mill-bundle: wrote ${OUT}`)
  } else {
    console.log(
      'mill-bundle: the baked grammar is STALE, pass --commit to write it',
    )
    process.exitCode = 1
  }
}

// run as a command, never on import (the pair imports bakedOf)
if (process.argv[1]?.endsWith('mill-bundle.ts')) {
  main()
}
